import uuid
from datetime import datetime

from pydantic import BaseModel, Field

from app.core.enums import MealType
from app.schemas.food import FoodRead

DIET_NOTICE = (
    "This plan is generated by software and is not medical or nutritional "
    "advice. Talk to a doctor or dietitian before changing your diet."
)

# --- What the client may send ----------------------------------------------


class DietPlanCreate(BaseModel):
    # Optional. Without it, the calorie target comes from the profile's goal.
    target_kcal: int | None = Field(
        default=None,
        gt=0,
        le=10000,
        description=(
            "Daily calories to plan for, instead of the target computed from "
            "your goal. It must stay inside the safety limits for your profile."
        ),
    )


# --- What the LLM must return ----------------------------------------------


class DietItemDraft(BaseModel):
    food_id: uuid.UUID
    grams: float = Field(gt=0, le=2000)


class DietMealDraft(BaseModel):
    meal_type: MealType
    items: list[DietItemDraft] = Field(min_length=2, max_length=6)


class DietPlanDraft(BaseModel):
    meals: list[DietMealDraft] = Field(min_length=1, max_length=6)


# --- What the API returns --------------------------------------------------


class NutrientsRead(BaseModel):
    kcal: int
    protein_g: int
    carbs_g: int
    fat_g: int


class DietPlanItemRead(BaseModel):
    position: int
    grams: float
    food: FoodRead
    nutrients: NutrientsRead


class DietPlanMealRead(BaseModel):
    position: int
    meal_type: MealType
    items: list[DietPlanItemRead]
    totals: NutrientsRead


class DietPlanSummary(BaseModel):
    id: uuid.UUID
    is_active: bool
    model: str
    created_at: datetime
    targets: NutrientsRead


class DietPlanRead(DietPlanSummary):
    # Computed in code from the catalog values, never by the LLM.
    totals: NutrientsRead
    meals: list[DietPlanMealRead]
    notice: str = DIET_NOTICE
